$audited = 0;
$missing = [];
$page = 1;
do {
    $result = $tools->call('publishing_list', ['page' => $page]);
    foreach ($result->items as $item) {
        $audited++;
        if (trim($item->meta_description) === '') {
            $missing[] = $item->id;
        }
    }
    $page = $result->nextPage;
} while ($page !== null);
sort($missing, SORT_NUMERIC);
return ['audited' => $audited, 'missing' => $missing];

