$page = 1;
$allItems = [];
while (true) {
    $resp = $tools->call('publishing_list', ['page'=>$page]);
    if (!isset($resp->items) || !is_array($resp->items)) break;
    foreach ($resp->items as $item) {
        $allItems[] = $item;
    }
    if ($resp->nextPage === null) {
        break;
    }
    $page = $resp->nextPage;
}
$audited = count($allItems);
$missing = [];
foreach ($allItems as $item) {
    if (isset($item->meta_description) && $item->meta_description === '') {
        $missing[] = $item->id;
    }
}
sort($missing, SORT_NUMERIC);
return ['audited'=>$audited, 'missing'=>$missing];

